/*
 xd11cc-single 数据库数据脚本
 ------------------------------------------------------------
 库名   : xd11cc_single
 内容   : 种子/基础数据（租户、用户、角色、菜单、字典、配置、工作流分类等）
 前置   : 先执行 xd11cc_single.sql 建表
 适用   : MySQL 8.0
 维护   : 种子数据变更后同步更新本文件

 包含的表（15 张）:
   system_tenant  system_config  system_menu  system_role  system_role_menu
   system_role_dept  system_dept  system_dept_post  system_post
   system_user  system_user_role
   workflow_category  workflow_expression_config
   system_dict_type  system_dict_data

 刻意不含:
   auth_client_config   第三方 app secret，按环境配置，不进仓库
   system_login_log / system_operate_log        日志
   workflow_instance / workflow_task_record     流程实例与任务流水
   mq_fail_message                              MQ 消费失败记录
   auth_social_user                             真实第三方账号绑定（含个人信息）
   system_notice / system_notice_user           业务数据
*/
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
















